#include "vehicle_bridge/frame_codec.hpp"
#include <algorithm>
namespace {constexpr uint8_t H=0x7b,T=0x7d;uint8_t checksum(const uint8_t* p,int n){uint8_t c=0;for(int i=0;i<n;++i)c^=p[i];return c;}int16_t word(uint8_t a,uint8_t b){return static_cast<int16_t>((a<<8)|b);} }
std::array<uint8_t,11> frame_codec::encode_velocity(double x,double y,double yaw){std::array<uint8_t,11> b{};b[0]=H;int16_t v[3]={(int16_t)(x*1000),(int16_t)(y*1000),(int16_t)(yaw*1000)};for(int i=0;i<3;++i){b[3+2*i]=v[i]>>8;b[4+2*i]=v[i];}b[9]=checksum(b.data(),9);b[10]=T;return b;}
bool frame_codec::decode_sensor(const std::array<uint8_t,24>& bytes,SensorFrame& o){std::array<uint8_t,24> b{};auto start=std::find(bytes.begin(),bytes.end(),H);if(start==bytes.end())return false;for(size_t i=0;i<b.size();++i)b[i]=bytes[(start-bytes.begin()+i)%bytes.size()];if(b.front()!=H||b.back()!=T||b[22]!=checksum(b.data(),22))return false;o.vx=word(b[2],b[3])*.001;o.vy=word(b[4],b[5])*.001;o.wz=word(b[6],b[7])*.001;o.ax=word(b[8],b[9])/1671.84;o.ay=word(b[10],b[11])/1671.84;o.az=word(b[12],b[13])/1671.84;o.gx=word(b[14],b[15])*.00026644;o.gy=word(b[16],b[17])*.00026644;o.gz=word(b[18],b[19])*.00026644;o.voltage=word(b[20],b[21])*.001;return true;}
